// Deixa só os números e confere os dígitos verificadores do CNPJ.
const entrada = $input.first().json;
const bruto = String(entrada.body?.cnpj ?? entrada.cnpj ?? '');
const cnpj = bruto.replace(/\D/g, '');
if (!cnpj) throw new Error('CNPJ não informado.');
if (cnpj.length !== 14 || /^(\d)\1{13}$/.test(cnpj)) throw new Error(`CNPJ "${bruto}" não tem 14 números válidos.`);
const dv = (base) => {
  const pesos = base.length === 12 ? [5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2] : [6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2];
  const soma = base.split('').reduce((s, n, i) => s + Number(n) * pesos[i], 0);
  const r = soma % 11;
  return r < 2 ? 0 : 11 - r;
};
const d1 = dv(cnpj.slice(0, 12));
const d2 = dv(cnpj.slice(0, 12) + d1);
if (`${d1}${d2}` !== cnpj.slice(12)) throw new Error(`CNPJ "${bruto}" tem dígito verificador errado.`);
const formatado = cnpj.replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})$/, '$1.$2.$3/$4-$5');
return [{ json: { cnpj, cnpj_formatado: formatado } }];

// Junta as duas consultas no formato que o portal usaria: o que preenche no cadastro, o aviso de situação e o que diverge entre as fontes.
const { cnpj, cnpj_formatado } = $('Conferir CNPJ').first().json;
const ba = $('Receita (BrasilAPI)').first().json;
const ws = $('Receita (CNPJ.ws)').first().json;

const ok = (r) => r && r.statusCode >= 200 && r.statusCode < 300 && r.body && typeof r.body === 'object';
const b = ok(ba) ? ba.body : null;
const w = ok(ws) ? ws.body : null;
const e = w?.estabelecimento ?? null;

const limpar = (v) => (v === null || v === undefined ? '' : String(v).replace(/\s+/g, ' ').trim());
const titulo = (v) => limpar(v).toLowerCase().replace(/(^|\s|\/|-)(\S)/g, (m, a, c) => a + c.toUpperCase()).replace(/\b(De|Da|Do|Das|Dos|E|Em|Por|Para)\b/g, (x) => x.toLowerCase());
const data = (v) => { const s = limpar(v).slice(0, 10); return /^\d{4}-\d{2}-\d{2}$/.test(s) ? s.split('-').reverse().join('/') : s; };
const cep = (v) => limpar(v).replace(/\D/g, '').replace(/^(\d{5})(\d{3})$/, '$1-$2');
const fone = (ddd, n) => { const t = (limpar(ddd) + limpar(n)).replace(/\D/g, ''); return t.length >= 10 ? t.replace(/^(\d{2})(\d{4,5})(\d{4})$/, '($1) $2-$3') : ''; };
const cnae = (cod, desc) => { const c0 = limpar(cod).replace(/\D/g, ''); const c = c0.length === 6 ? '0' + c0 : c0; const f = c.length === 7 ? c.replace(/^(\d{4})(\d)(\d{2})$/, '$1-$2/$3') : c; return [f, limpar(desc)].filter(Boolean).join(' '); };

// Situação na Receita (ATIVA, BAIXADA, SUSPENSA, INAPTA, NULA).
const situacao = limpar(b?.descricao_situacao_cadastral ?? e?.situacao_cadastral).toUpperCase();
const situacaoDesde = data(b?.data_situacao_cadastral ?? e?.data_situacao_cadastral);
const motivo = limpar(b?.descricao_motivo_situacao_cadastral ?? e?.motivo_situacao_cadastral?.descricao);

// Inscrição estadual (só a CNPJ.ws traz): a ativa do estado da empresa.
const uf = limpar(b?.uf ?? e?.estado?.sigla).toUpperCase();
const ies = Array.isArray(e?.inscricoes_estaduais) ? e.inscricoes_estaduais : [];
const ie = ies.find((x) => x.ativo && (x.estado?.sigla ?? '').toUpperCase() === uf) ?? ies.find((x) => x.ativo) ?? null;

const tipoLog = limpar(b?.descricao_tipo_de_logradouro ?? e?.tipo_logradouro);
const logradouro = limpar(b?.logradouro ?? e?.logradouro);

// Campos do F.31 que o portal preencheria (o fornecedor confere e completa).
const preenche = {
  razao_social: limpar(b?.razao_social ?? w?.razao_social).toUpperCase(),
  nome_fantasia: limpar(b?.nome_fantasia ?? e?.nome_fantasia),
  ramo: titulo(b?.cnae_fiscal_descricao ?? e?.atividade_principal?.descricao),
  cep: cep(b?.cep ?? e?.cep),
  endereco: titulo([tipoLog, logradouro].filter(Boolean).join(' ')),
  numero: limpar(b?.numero ?? e?.numero),
  complemento: titulo(b?.complemento ?? e?.complemento),
  bairro: titulo(b?.bairro ?? e?.bairro),
  cidade: titulo(e?.cidade?.nome ?? b?.municipio),
  estado: uf,
  telefone: fone(b?.ddd_telefone_1?.slice?.(0, 2), b?.ddd_telefone_1?.slice?.(2)) || fone(e?.ddd1, e?.telefone1),
  email_empresa: limpar(b?.email ?? e?.email).toLowerCase(),
  inscricao_estadual: limpar(ie?.inscricao_estadual),
};

const aviso = !situacao
  ? 'Não foi possível ler a situação na Receita. Confira o CNPJ manualmente.'
  : situacao === 'ATIVA'
    ? ''
    : `CNPJ ${situacao} na Receita${situacaoDesde ? ` desde ${situacaoDesde}` : ''}${motivo ? ` (${titulo(motivo)})` : ''}.`;

const secundarios = Array.isArray(b?.cnaes_secundarios)
  ? b.cnaes_secundarios.filter((x) => x.codigo).map((x) => cnae(x.codigo, x.descricao))
  : Array.isArray(e?.atividades_secundarias) ? e.atividades_secundarias.map((x) => cnae(x.subclasse ?? x.id, x.descricao)) : [];

// Onde as duas fontes dizem coisas diferentes (ajuda a escolher a fonte).
const comparar = (nome, x, y) => {
  const norm = (v) => limpar(v).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase();
  const a = norm(x); const c = norm(y);
  return a && c && a !== c ? { campo: nome, brasilapi: limpar(x), cnpj_ws: limpar(y) } : null;
};
const divergencias = b && w ? [
  comparar('razão social', b.razao_social, w.razao_social),
  comparar('situação', b.descricao_situacao_cadastral, e?.situacao_cadastral),
  comparar('CEP', limpar(b.cep).replace(/\D/g, ''), limpar(e?.cep).replace(/\D/g, '')),
  comparar('número', b.numero, e?.numero),
  comparar('cidade', b.municipio, e?.cidade?.nome),
].filter(Boolean) : [];

return [{
  json: {
    cnpj: cnpj_formatado,
    consulta: {
      brasilapi: ba?.statusCode ? `${ba.statusCode}${b ? ' ok' : ' sem dados'}` : 'sem resposta',
      cnpj_ws: ws?.statusCode ? `${ws.statusCode}${w ? ' ok' : ' sem dados'}` : 'sem resposta',
    },
    situacao_receita: situacao || '(não informada)',
    situacao_desde: situacaoDesde,
    aviso_para_o_suprimentos: aviso || 'Nenhum: CNPJ ativo.',
    preenche_no_portal: preenche,
    campos_vazios: Object.entries(preenche).filter(([, v]) => !v).map(([k]) => k),
    so_para_consulta: {
      abertura: data(b?.data_inicio_atividade ?? e?.data_inicio_atividade),
      natureza_juridica: limpar(b?.natureza_juridica ?? w?.natureza_juridica?.descricao),
      porte: limpar(b?.porte ?? b?.descricao_porte ?? w?.porte?.descricao),
      capital_social: b?.capital_social ?? w?.capital_social ?? null,
      simples: b ? (b.opcao_pelo_simples ? 'Sim' : 'Não') : limpar(w?.simples?.simples),
      mei: b ? (b.opcao_pelo_mei ? 'Sim' : 'Não') : limpar(w?.simples?.mei),
      cnae_principal: cnae(b?.cnae_fiscal ?? e?.atividade_principal?.subclasse, b?.cnae_fiscal_descricao ?? e?.atividade_principal?.descricao),
      cnaes_secundarios: secundarios,
      quantidade_de_socios: Array.isArray(b?.qsa) ? b.qsa.length : Array.isArray(w?.socios) ? w.socios.length : null,
    },
    divergencias_entre_fontes: divergencias,
  },
}];
